#!/usr/bin/env python3
"""Pack a TEX label in the archive's compressed form and write a C/asm header.
  pack_label.py <in.tex> <out.bin> <out.h> <rom_address>"""
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import nm_assets as A  # noqa: E402

tex = open(sys.argv[1], 'rb').read()
packed = A.pack_asset(tex)
back, _ = A.lzss_decompress(packed, 4, len(tex))
if back != tex:
    sys.exit('LZSS round trip failed')
packed += b'\0' * (-len(packed) % 8)
open(sys.argv[2], 'wb').write(packed)
open(sys.argv[3], 'w').write(
    '/* generated by tools/pack_label.py */\n'
    f'#define LABEL_ROM    {int(sys.argv[4], 0):#x}\n'
    f'#define LABEL_SIZE   {len(tex):#x}\n'
    f'#define LABEL_PACKED {len(packed):#x}\n')
print(f'label: {len(tex)} bytes -> {len(packed)} packed')
